"""One economic façade for the DSH pilot: the model, the validation and the fallback read the
same numbers here.

Nothing is re-derived: C is the kit's published function (`arena_kit.cost`), the cost-to-price
inversion and the grid of structures are Pegasus' (`pegasus.economics`). What this module adds is
the standing of each number: `commercial` is exact accounting from the case file and the
supplier's standard terms; the relationship charge (strategic and bottleneck goals) depends on
the supplier's full cost, which we only estimate - it is reported apart, with where the estimate
comes from, and as unknown when we hold none.
"""

from arena_kit.cost import RELATIONSHIP_GOALS, closing_terms, cost_breakdown, must_haves_ok

from ..pegasus import economics as eco

INF = float("inf")


def charge_applies(case):
    """The arena charges for a squeezed supplier in this case (stabilise, secure_supply)."""
    b = case["buyer"]
    return bool(b.get("category_goal") in RELATIONSHIP_GOALS and b.get("relationship_eur_per_point")
                and b.get("sustainable_margin_pct"))


def clean(terms):
    return {k: v for k, v in (terms or {}).items() if not k.startswith("_")}


def problems(case, terms):
    """Why the arena would refuse this term sheet (422), [] when it is well formed."""
    out, opts = [], case.get("term_options", {})
    for f in case["negotiable"]:
        if terms.get(f) is None and not (f == "index_clause" and f in terms):
            out.append(f"missing field {f}")
    for f, v in terms.items():
        if f not in case["negotiable"]:
            out.append(f"{f} is not negotiable in this case")
        elif f == "unit_price":
            if not isinstance(v, int | float) or isinstance(v, bool) or v != v or v <= 0 or v in (INF, -INF):
                out.append("unit_price must be a positive number")
            elif round(v, 2) != v:
                out.append("unit_price takes 2 decimals")
        elif opts.get(f) and v not in opts[f]:
            out.append(f"{f}={v!r} is not an allowed option {opts[f]}")
    return out


def evaluate(case, terms, std=None, estimate=None):
    """What a term sheet costs the buyer. `std`: the supplier's standard terms, which fill what
    the sheet leaves out; `estimate`: our estimate of the supplier (`supplier_value`'s argument)
    or None. Never raises: a sheet that cannot be costed is invalid at an unknown cost."""
    terms, std = clean(terms), clean(std)
    out = {"terms": terms, "problems": problems(case, terms), "must_haves_ok": None, "commercial_eur": None,
           "relationship_eur": None, "relationship": "does not apply", "total_eur": None, "breakdown": None}
    if terms.get("unit_price") is None:
        out["problems"].append("no unit_price: a sheet without a price has no cost")
        return out
    try:
        parts = cost_breakdown(case, terms, std, estimate)
        out["must_haves_ok"] = must_haves_ok(case, terms, std)
    except (KeyError, TypeError, ValueError) as e:
        out["problems"].append(f"cannot be costed: {type(e).__name__} {e}")
        return out
    rel = parts.pop("relationship", 0.0)
    out["breakdown"] = {k: round(v, 2) for k, v in parts.items() if abs(v) >= 0.005}
    out["commercial_eur"] = round(sum(parts.values()), 2)
    if charge_applies(case):
        if estimate:
            out["relationship_eur"] = round(rel, 2)
            out["relationship"] = "estimated from our estimate of the supplier's full cost - not a fact"
        else:
            out["relationship"] = ("applies, unknown: we hold no estimate of the supplier's full cost; "
                                   "commercial_eur is then an optimistic bound")
    out["total_eur"] = round(out["commercial_eur"] + (out["relationship_eur"] or 0.0), 2)
    if out["must_haves_ok"] is False:
        out["problems"].append("breaks a must-have: a deal on it scores 0")
    return out


def cost(case, terms, std=None, estimate=None):
    """C in EUR (relationship estimate included when we hold one), inf when it cannot be costed."""
    e = evaluate(case, terms, std, estimate)
    return INF if e["total_eur"] is None else e["total_eur"]


def alternative(case):
    """C of what the buyer gets without a deal, None when there is no alternative."""
    c = eco.alt_cost(case)
    return None if c == INF else round(c, 2)


def structures_for_target(case, target_eur, std=None, estimate=None, restrict=None, limit=12):
    """Every allowed combination of the non-price terms, each at the unit price that makes it cost
    the buyer `target_eur`. At equal cost for us the highest such price is returned: it is the
    sheet the supplier likes most. `restrict`: {field: [allowed values]} chosen by the caller.
    A combination that cannot get as cheap as the target comes back with `reached: false` and its
    cheapest attainable cost (the bottom of the U when a relationship charge applies)."""
    std = clean(std)
    priced_std = {**std, "_supplier": estimate} if estimate else std
    grid = eco.grid(case)
    out = []
    for structure in grid:
        if restrict and any(f in restrict and structure.get(f) not in restrict[f] for f in structure):
            continue
        price = eco.price_for(case, structure, target_eur, priced_std)
        terms = eco.sheet(case, structure, price)
        e = evaluate(case, terms, std, estimate)
        if e["total_eur"] is None or e["must_haves_ok"] is False or e["problems"]:
            continue
        out.append({"terms": terms, "total_eur": e["total_eur"], "commercial_eur": e["commercial_eur"],
                    "relationship_eur": e["relationship_eur"],
                    "reached": abs(e["total_eur"] - target_eur) <= max(1.0, 2e-4 * abs(target_eur))})
    out.sort(key=lambda x: (not x["reached"], -x["terms"]["unit_price"]))
    return {"target_eur": target_eur, "combinations_in_grid": len(grid), "searched": "all" if len(grid) < eco.MAX_GRID
            else f"first {eco.MAX_GRID} only", "returned": min(limit, len(out)), "matching": len(out),
            "sheets": out[:limit]}


def _asked(case, msg, std, estimate):
    costs = [cost(case, ts.get("terms", ts), std, estimate) for ts in msg.get("term_sheets") or []]
    costs = [c for c in costs if c != INF]
    return min(costs) if costs else None


def movement(case, events, std=None, estimate=None):
    """How far each side has moved, in our cost units. For every message that carried term sheets,
    the cheapest of them for us. `supplier_since_our_last_move` > 0: it came towards us after our
    last message; 0: it held; < 0: it went backwards."""
    ours = [(i, c) for i, m in enumerate(events) if m.get("from") == "buyer"
            and (c := _asked(case, m, std, estimate)) is not None]
    theirs = [(i, c) for i, m in enumerate(events) if m.get("from") != "buyer"
              and (c := _asked(case, m, std, estimate)) is not None]
    out = {"our_asks_eur": [round(c, 2) for _, c in ours], "supplier_offers_eur": [round(c, 2) for _, c in theirs]}
    if not theirs:
        return out
    now = theirs[-1][1]
    out["supplier_total_move_eur"] = round(theirs[0][1] - now, 2)
    if ours:
        last_i, last_c = ours[-1]
        before = [c for i, c in theirs if i < last_i]
        after = [c for i, c in theirs if i > last_i]
        if before and after:
            out["supplier_since_our_last_move_eur"] = round(before[-1] - after[-1], 2)
        if len(ours) > 1:
            out["our_last_move_eur"] = round(last_c - ours[-2][1], 2)
        out["gap_eur"] = round(now - last_c, 2)
        first_gap = theirs[0][1] - ours[0][1]
        if first_gap > 0:
            out["gap_closed_by_supplier_pct"] = round(100 * (theirs[0][1] - now) / first_gap, 1)
            out["gap_closed_by_us_pct"] = round(100 * (last_c - ours[0][1]) / first_gap, 1)
    return out

"""The factual state of one case, built from what the arena answered - never from what the model
remembers. The model gets `snapshot()`; tools and the coordinator read and write under `lock`.
"""

import threading
import time

from arena_kit.play import ENDED, MOVE_LIMIT_S, latest

from ..pegasus import economics as eco
from ..pegasus.agent import supplier_reference
from . import economics

BODY_CHARS = 3000  # of a supplier e-mail shown in the snapshot; `read_thread` gives all of it


class CaseState:
    def __init__(self, case, threads, package=None, clock=time.monotonic):
        self.case, self.threads, self.pkg, self.clock = case, threads, package, clock
        self.lock = threading.RLock()
        self.version = 0
        self.inflight = set()  # suppliers we are waiting on: our message is out, no reply yet
        self.arrived = {sid: clock() for sid in threads}  # when the supplier's latest e-mail came in
        self.errors = {}  # supplier -> what the arena last refused, shown to the model once
        self.hypotheses = []  # the model's revisable notes: {"id", "text", "status", "sources", ...}
        self.result = None
        self.std, self.estimate = {}, {}
        facts = getattr(package, "facts", None) or {}
        self.facts = {**facts, **(case.get("facts") or {})}
        for sid, events in threads.items():
            self._model_supplier(sid, events)

    def _model_supplier(self, sid, events):
        self.std[sid] = supplier_reference(self.case, events)
        first = next((m for m in events if m.get("from") != "buyer"), {})
        sheets = first.get("term_sheets") or []
        price = (sheets[0].get("terms") or {}).get("unit_price") if sheets else None
        self.estimate[sid] = eco.supplier_model(self.case, self.std[sid], price, self.facts, sid)

    # -- events --------------------------------------------------------------------------------
    def sent(self, sid, message):
        with self.lock:
            self.threads[sid].append({**message, "from": "buyer"})
            self.inflight.add(sid)
            self.version += 1

    def replied(self, sid, reply):
        with self.lock:
            self.threads[sid].append(reply)
            self.inflight.discard(sid)
            self.arrived[sid] = self.clock()
            self.version += 1

    def refused(self, sid, message, detail):
        """The arena refused our message (422): nothing happened, no round was used."""
        with self.lock:
            if self.threads[sid] and self.threads[sid][-1].get("from") == "buyer":
                self.threads[sid].pop()
            self.inflight.discard(sid)
            self.errors[sid] = str(detail)[:600]
            self.version += 1

    # -- reads ---------------------------------------------------------------------------------
    def status(self, sid):
        return latest(self.threads[sid]).get("status") or "open"

    def live(self):
        return [s for s in self.threads if self.status(s) not in ENDED]

    def moves_left(self, sid):
        return self.case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in self.threads[sid])

    def seconds_left(self, sid):
        return MOVE_LIMIT_S - (self.clock() - self.arrived[sid])

    def ready(self):
        """Suppliers whose e-mail waits for our answer."""
        return [s for s in self.live() if s not in self.inflight and self.threads[s][-1].get("from") != "buyer"]

    def standing(self, sid):
        """(term_sheet_id, terms) of the sheet we could accept now, else (None, {})."""
        sheets = latest(self.threads[sid]).get("term_sheets") or []
        return (sheets[0].get("term_sheet_id"), sheets[0].get("terms") or {}) if sheets else (None, {})

    def evaluate(self, sid, terms):
        return economics.evaluate(self.case, terms, self.std.get(sid), self.estimate.get(sid))

    def cost(self, sid, terms):
        return economics.cost(self.case, terms, self.std.get(sid), self.estimate.get(sid))

    def best_standing(self):
        """(cost, supplier, term_sheet_id) of the cheapest signable sheet that keeps the must-haves."""
        best = None
        for sid in self.live():
            sheet_id, terms = self.standing(sid)
            e = self.evaluate(sid, terms) if sheet_id else None
            if e and e["total_eur"] is not None and e["must_haves_ok"]:
                best = min(best or (e["total_eur"], sid, sheet_id), (e["total_eur"], sid, sheet_id))
        return best

    def c_open(self):
        """C of the cheapest opening quote that keeps the must-haves: the zero point of the score."""
        out = None
        for sid, events in self.threads.items():
            first = next((m for m in events if m.get("from") != "buyer"), {})
            for ts in (first.get("term_sheets") or [])[:1]:
                e = self.evaluate(sid, ts.get("terms") or {})
                if e["total_eur"] is not None and e["must_haves_ok"]:
                    out = e["total_eur"] if out is None else min(out, e["total_eur"])
        return out

    def _thread_view(self, sid):
        events = self.threads[sid]
        last = latest(events)
        sheets = []
        for i, ts in enumerate(last.get("term_sheets") or []):
            e = self.evaluate(sid, ts.get("terms") or {})
            sheets.append({"term_sheet_id": ts.get("term_sheet_id"), "can_be_accepted_now": i == 0,
                           "terms": ts.get("terms"), "cost_eur": e["total_eur"], "commercial_eur": e["commercial_eur"],
                           "relationship_eur": e["relationship_eur"], "must_haves_ok": e["must_haves_ok"]})
        view = {
            "supplier_id": sid,
            "status": self.status(sid),
            "awaits_your_answer": sid in self.ready(),
            "our_message_in_flight": sid in self.inflight,
            "seconds_left_to_answer": round(self.seconds_left(sid), 1) if sid in self.ready() else None,
            "messages_you_may_still_send": self.moves_left(sid),
            "supplier_sheets": sheets,
            "fields_it_left_to_its_standard_terms": last.get("missing_fields") or [],
            "its_standard_terms": economics.clean(self.std.get(sid)),
            "checks_of_your_last_arguments": last.get("claim_results") or [],
            "its_last_email": (last.get("body") or "")[:BODY_CHARS],
            "attachments_of_its_last_email": [a.get("name") for a in last.get("attachments") or []],
            "movement": economics.movement(self.case, events, self.std.get(sid), self.estimate.get(sid)),
        }
        if sid in self.errors:
            view["arena_refused_your_last_message"] = self.errors[sid]
        if self.estimate.get(sid):
            est = self.estimate[sid]
            view["our_estimate_of_this_supplier"] = {
                "full_cost_per_unit": round(est["full_cost"], 2), "its_cost_of_money": est["interest_rate"],
                "standing": "estimate from the part's should-cost and the correspondence, not a fact"}
        return view

    def snapshot(self):
        """Everything the model needs to decide, as plain data."""
        with self.lock:
            case, b = self.case, self.case["buyer"]
            alt = b.get("alternative") or {}
            best = self.best_standing()
            return {
                "state_version": self.version,
                "case": {
                    "case_id": case["case_id"], "type": case.get("type"), "title": case.get("title"),
                    "briefing": case.get("briefing"), "parts": case.get("parts"), "category_goal": b.get("category_goal"),
                    "negotiable_fields": case["negotiable"], "term_options": case.get("term_options", {}),
                    "fixed_terms": case.get("fixed_terms", {}), "must_haves": b.get("must_haves", []),
                    "messages_per_thread": case.get("round_limit", 10), "data_ids_the_case_points_to": case.get("refs", []),
                    "buyer": {k: v for k, v in b.items() if k not in ("alternative", "must_haves")},
                },
                "without_a_deal": {"kind": alt.get("kind", "none"), "terms": alt.get("terms"),
                                   "cost_eur": economics.alternative(case),
                                   "note": "no deal scores this alternative; with no alternative it scores 0"},
                "relationship_charge": ("applies: a deal that leaves the supplier below its sustainable margin costs us"
                                        if economics.charge_applies(case) else "does not apply in this case"),
                "cost_of_cheapest_opening_quote_eur": self.c_open(),
                "cheapest_sheet_you_could_accept_now": (
                    {"cost_eur": best[0], "supplier_id": best[1], "term_sheet_id": best[2]} if best else None),
                "threads": [self._thread_view(s) for s in self.threads],
                "your_notes": self.hypotheses,
            }

"""What the model wants to send, checked before anything leaves.

`prepare` never rewrites a decision. It returns `errors` (the arena would refuse it, it would
score 0, or it addresses a thread that cannot be answered now: nothing is sent) and
`diagnostics` (facts the model should know before committing - it may keep its choice).
Protocol and mandate are enforced here; tactics are not.
"""

import hashlib
import json
import re

from . import economics

MAX_SUBJECT, MAX_BODY, MAX_SHEETS, MAX_REFS = 300, 8000, 3, 20
ID_RE = re.compile(r"\b(?:idx|quote|sc|qn|po|cost|fc|news|doc|ctr|offer):[A-Za-z0-9_.:@/-]*[A-Za-z0-9]")


def fingerprint(batch):
    return hashlib.sha256(json.dumps(batch, sort_keys=True, default=str).encode()).hexdigest()[:16]


def known_ids(state):
    """IDs a message may cite: the data package, the case's own facts and refs, and the offers
    made in this session."""
    ids = set(state.facts) | set(state.case.get("refs") or [])
    for events in state.threads.values():
        for m in events:
            ids.update(ts["term_sheet_id"] for ts in m.get("term_sheets") or [] if ts.get("term_sheet_id"))
    return ids


def _email(state, mail, seen, errors, diagnostics, costs):
    sid = mail.get("supplier_id")
    where = f"e-mail to {sid}"
    if sid not in state.threads:
        errors.append(f"{where}: unknown supplier; the suppliers of this case are {list(state.threads)}")
        return None
    if sid in seen:
        errors.append(f"{where}: at most one e-mail per supplier in a decision")
        return None
    seen.add(sid)
    if sid not in state.live():
        errors.append(f"{where}: this thread has ended ({state.status(sid)})")
    elif sid in state.inflight:
        errors.append(f"{where}: your previous e-mail is still unanswered - wait for the reply")
    elif state.moves_left(sid) <= 0:
        errors.append(f"{where}: no message left in this thread - you may only accept or walk away")
    subject, body = str(mail.get("subject") or ""), str(mail.get("body") or "")
    if not body.strip():
        errors.append(f"{where}: empty body")
    if len(subject) > MAX_SUBJECT:
        errors.append(f"{where}: subject over {MAX_SUBJECT} characters")
    if len(body) > MAX_BODY:
        errors.append(f"{where}: body over {MAX_BODY} characters")
    sheets = [dict(ts.get("terms", ts)) for ts in mail.get("term_sheets") or []]
    if len(sheets) > MAX_SHEETS:
        errors.append(f"{where}: {len(sheets)} term sheets, at most {MAX_SHEETS}")
    best = state.best_standing()
    movement = economics.movement(state.case, state.threads[sid], state.std.get(sid), state.estimate.get(sid))
    last_ask = (movement.get("our_asks_eur") or [None])[-1]
    evaluated = []
    for n, terms in enumerate(sheets, 1):
        e = state.evaluate(sid, terms)
        for p in e["problems"]:
            errors.append(f"{where}, sheet {n}: {p}")
        evaluated.append(e)
        costs.append({"supplier_id": sid, "sheet": n, "terms": terms, "cost_eur": e["total_eur"],
                      "commercial_eur": e["commercial_eur"], "relationship_eur": e["relationship_eur"],
                      "relationship": e["relationship"]})
        price = terms.get("unit_price")
        if isinstance(price, int | float) and not any(s in body for s in (f"{price:.2f}", f"{price:.2f}".replace(".", ","))):
            diagnostics.append(f"{where}, sheet {n}: the price {price:.2f} is not written in the body; "
                               "only the term sheet binds, but text and sheet should say the same")
        if e["total_eur"] is not None and best and e["total_eur"] > best[0] + 0.005:
            diagnostics.append(
                f"{where}, sheet {n}: it would cost us {e['total_eur']:.2f} EUR, more than a sheet you can accept "
                f"right now ({best[2]} from {best[1]}: {best[0]:.2f} EUR)")
    asks = [e["total_eur"] for e in evaluated if e["total_eur"] is not None]
    if asks and last_ask is not None:
        step = min(asks) - last_ask
        if step > 0.005:
            since = movement.get("supplier_since_our_last_move_eur")
            moved = "unknown" if since is None else f"{since:.2f} EUR"
            diagnostics.append(f"{where}: you concede {step:.2f} EUR against your last ask; "
                               f"the supplier's move since that ask: {moved}")
        elif step < -0.005:
            diagnostics.append(f"{where}: this asks {-step:.2f} EUR more than your last ask (you are taking back a concession)")
    if state.status(sid) == "final_offer":
        diagnostics.append(f"{where}: its last e-mail was marked final_offer - its last word; pushing further may make it walk")
    refs = [str(r) for r in mail.get("refs") or []]
    if len(refs) > MAX_REFS:
        errors.append(f"{where}: {len(refs)} refs, at most {MAX_REFS}")
    known = known_ids(state)
    for ref in sorted(set(refs) | set(ID_RE.findall(body))):
        if ref not in known:
            errors.append(f"{where}: {ref} is not a known data ID - an unknown ID is counted as contradicted and costs trust")
        elif ref not in state.facts and not ref.startswith("offer:"):
            diagnostics.append(f"{where}: {ref} is named by the case but its value is not in our data - "
                               "cite it without a figure, or the figure may be found wrong")
    out = {"supplier_id": sid, "message": {"subject": subject, "body": body, "term_sheets": [{"terms": t} for t in sheets]}}
    if refs:
        out["message"]["refs"] = refs
    return out


def _close(state, close, errors, diagnostics):
    kind = close.get("type")
    alt = economics.alternative(state.case)
    if kind == "walk_away":
        best = state.best_standing()
        if best and (alt is None or best[0] < alt):
            diagnostics.append(f"walking away gives up a signable sheet at {best[0]:.2f} EUR ({best[2]}); "
                               + ("without a deal this case scores 0" if alt is None else f"the alternative costs {alt:.2f} EUR"))
        live = state.live()
        if not live:
            errors.append("no live thread to close")
            return None
        return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
    if kind != "accept":
        errors.append("close.type must be accept or walk_away")
        return None
    sid, sheet_id = close.get("supplier_id"), close.get("term_sheet_id")
    if sid not in state.threads or sid not in state.live():
        errors.append(f"accept: {sid} is not a live supplier of this case")
        return None
    standing_id, terms = state.standing(sid)
    if sheet_id != standing_id:
        errors.append(f"accept: only the supplier's standing sheet can be accepted, which is {standing_id} for {sid}; "
                      "a package it only describes must first come back as its standing offer")
        return None
    if sid in state.inflight:
        errors.append(f"accept: your e-mail to {sid} is still unanswered and may change its offer - wait for the reply")
    e = state.evaluate(sid, terms)
    if e["must_haves_ok"] is False:
        errors.append("accept: this sheet breaks a must-have - the deal would score 0")
    best = state.best_standing()
    if best and e["total_eur"] is not None and best[0] < e["total_eur"] - 0.005:
        diagnostics.append(f"accept: {best[2]} from {best[1]} is signable and cheaper ({best[0]:.2f} against {e['total_eur']:.2f} EUR)")
    if alt is not None and e["total_eur"] is not None and e["total_eur"] > alt:
        diagnostics.append(f"accept: this deal costs {e['total_eur']:.2f} EUR, more than the alternative without a deal ({alt:.2f} EUR)")
    waiting = sorted(state.inflight - {sid})
    if waiting:
        diagnostics.append(f"accept: replies from {waiting} are still on their way; accepting ends the case for all")
    return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}},
            "cost_eur": e["total_eur"]}


def prepare(state, decision):
    """{"ok", "errors", "diagnostics", "costs", "batch"}; `batch` is what would be sent, None on errors."""
    errors, diagnostics, costs = [], [], []
    if not isinstance(decision, dict):
        return {"ok": False, "errors": ["decision must be an object with `emails` or `close`"], "diagnostics": [],
                "costs": [], "batch": None}
    emails, close = decision.get("emails") or [], decision.get("close")
    if emails and close:
        errors.append("a decision is either e-mails or a close (accept / walk_away), never both")
    if not emails and not close:
        errors.append("empty decision: give `emails` or `close`")
    batch = {"emails": [], "close": None, "note": str(decision.get("note") or "")[:600]}
    with state.lock:
        seen = set()
        for mail in emails if not close else []:
            if isinstance(mail, dict) and (m := _email(state, mail, seen, errors, diagnostics, costs)):
                batch["emails"].append(m)
        if close and not emails:
            batch["close"] = _close(state, close if isinstance(close, dict) else {}, errors, diagnostics)
        unanswered = [s for s in state.ready() if s not in seen] if emails else []
        if unanswered:
            diagnostics.append(f"no e-mail for {unanswered}: their 60-second clocks keep running; "
                               "a thread left unanswered times out and repeats your last offer")
    ok = not errors
    return {"ok": ok, "errors": errors, "diagnostics": diagnostics, "costs": costs, "batch": batch if ok else None}

"""The model's tools, served to DeepSeek Harness over MCP (local Streamable HTTP).

`Desk` holds the open decisions; every tool takes the opaque `decision_id` the coordinator gave
the model for this turn, and the desk derives the case from it - the model never names a case.
`commit_decision` is the only tool with an effect, and even it sends nothing: it hands a
validated, immutable batch to the coordinator, which is the only thing that talks to the arena.
The tool methods are plain Python (tested without MCP); `build_server` only wraps them.
"""

import logging
import secrets
import socket
import threading
import time

from . import economics, validation

log = logging.getLogger("pegasus.dsh")

ATTACHMENT_CHARS = 6000
MAX_ROWS = 50


class Decision:
    """One turn of the model on one case: a lease that is active, committed or expired."""

    def __init__(self, state, budget_s, clock=time.monotonic):
        self.id = "dec-" + secrets.token_hex(6)
        self.state, self.clock = state, clock
        self.deadline = clock() + budget_s
        self.drafts, self.batch, self.status = {}, None, "active"
        self.done = threading.Event()
        self.calls = []  # (tool, seconds since the lease opened): the trace of the turn
        self.opened = clock()

    def seconds_left(self):
        return self.deadline - self.clock()

    def expire(self):
        if self.status == "active":
            self.status = "expired"


class Desk:
    def __init__(self):
        self.lock = threading.Lock()
        self.decisions = {}

    def open(self, state, budget_s):
        d = Decision(state, budget_s)
        with self.lock:
            self.decisions[d.id] = d
        return d

    def _get(self, decision_id, tool):
        d = self.decisions.get(decision_id)
        if d is None:
            return None, {"error": "UNKNOWN_DECISION", "detail": "use the decision_id given in this turn's message"}
        d.calls.append((tool, round(d.clock() - d.opened, 2)))
        return d, None

    def _open(self, decision_id, tool):
        """For tools that prepare or engage: the lease must still be active and in time."""
        d, err = self._get(decision_id, tool)
        if err:
            return None, err
        if d.status == "committed":
            return None, {"error": "DECISION_COMMITTED", "detail": "this turn's decision is already engaged; stop here"}
        if d.status == "expired" or d.seconds_left() <= 0:
            d.expire()
            return None, {"error": "EXPIRED_DECISION", "detail": "this turn's time is over; nothing more can be sent now"}
        return d, None

    # -- read-only tools ------------------------------------------------------------------------
    def get_case_state(self, decision_id):
        d, err = self._get(decision_id, "get_case_state")
        if err:
            return err
        return {**d.state.snapshot(), "seconds_left_in_this_turn": round(d.seconds_left(), 1)}

    def read_thread(self, decision_id, supplier_id):
        d, err = self._get(decision_id, "read_thread")
        if err:
            return err
        events = d.state.threads.get(supplier_id)
        if events is None:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(d.state.threads)}
        out = []
        for m in events:
            item = {"from": "you" if m.get("from") == "buyer" else (m.get("from") or supplier_id),
                    "subject": m.get("subject"), "body": m.get("body"), "term_sheets": m.get("term_sheets") or []}
            if m.get("from") != "buyer":
                item.update(status=m.get("status"), missing_fields=m.get("missing_fields") or [],
                            claim_results=m.get("claim_results") or [], signals=m.get("signals") or {})
                item["attachments"] = [{"name": a.get("name"), "text": (a.get("text") or "")[:ATTACHMENT_CHARS]}
                                       for a in m.get("attachments") or []]
            elif m.get("refs"):
                item["refs"] = m["refs"]
            out.append(item)
        return {"supplier_id": supplier_id, "messages": out}

    def evaluate_offers(self, decision_id, supplier_id, term_sheets):
        d, err = self._get(decision_id, "evaluate_offers")
        if err:
            return err
        if supplier_id not in d.state.threads:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(d.state.threads)}
        out = [d.state.evaluate(supplier_id, dict(ts.get("terms", ts))) for ts in term_sheets or []]
        totals = [e["total_eur"] for e in out if e["total_eur"] is not None]
        return {"supplier_id": supplier_id, "evaluations": out,
                "cheapest_for_us_eur": min(totals) if totals else None,
                "alternative_without_a_deal_eur": economics.alternative(d.state.case)}

    def search_structures(self, decision_id, supplier_id, target_cost_eur, restrict=None, limit=12):
        d, err = self._get(decision_id, "search_structures")
        if err:
            return err
        st = d.state
        if supplier_id not in st.threads:
            return {"error": "UNKNOWN_SUPPLIER", "suppliers": list(st.threads)}
        try:
            target = float(target_cost_eur)
        except (TypeError, ValueError):
            return {"error": "INVALID_TERMS", "detail": "target_cost_eur must be a number of EUR"}
        return {"supplier_id": supplier_id, **economics.structures_for_target(
            st.case, target, st.std.get(supplier_id), st.estimate.get(supplier_id), restrict or None,
            max(1, min(int(limit or 12), 40)))}

    def lookup_facts(self, decision_id, ids):
        d, err = self._get(decision_id, "lookup_facts")
        if err:
            return err
        st, out = d.state, {}
        offers = {ts["term_sheet_id"]: {"supplier": sid, "terms": ts.get("terms")}
                  for sid, events in st.threads.items() for m in events
                  for ts in m.get("term_sheets") or [] if ts.get("term_sheet_id")}
        for ref in (ids or [])[:40]:
            if ref in st.facts:
                out[ref] = st.facts[ref]
            elif ref in offers:
                out[ref] = offers[ref]
            elif ref in (st.case.get("refs") or []):
                out[ref] = {"known": False, "note": "named by the case, value not in our data"}
            else:
                out[ref] = None
        return {"facts": out, "note": "null: not a known ID - do not cite it"}

    def query_data(self, decision_id, sql, limit=20):
        d, err = self._get(decision_id, "query_data")
        if err:
            return err
        if d.state.pkg is None:
            return {"error": "NO_DATA_PACKAGE"}
        try:
            return {"rows": d.state.pkg.query(sql, limit=max(1, min(int(limit or 20), MAX_ROWS)))}
        except Exception as e:  # a bad query is the model's to fix, never a crash of the turn
            return {"error": "QUERY_FAILED", "detail": f"{type(e).__name__}: {e}"[:400]}

    def update_hypotheses(self, decision_id, notes):
        d, err = self._get(decision_id, "update_hypotheses")
        if err:
            return err
        st = d.state
        with st.lock:
            by_id = {h["id"]: h for h in st.hypotheses}
            for n in notes or []:
                if not isinstance(n, dict) or not str(n.get("text") or "").strip():
                    continue
                hid = n.get("id") or f"h{len(st.hypotheses) + 1}"
                note = {"id": hid, "text": str(n["text"])[:500], "status": n.get("status") or "supposed",
                        "sources": [str(s)[:80] for s in n.get("sources") or []][:8]}
                if hid in by_id:
                    by_id[hid].update(note)
                else:
                    st.hypotheses.append(note)
                    by_id[hid] = note
            return {"your_notes": st.hypotheses}

    # -- prepare and engage -----------------------------------------------------------------------
    def prepare_decision(self, decision_id, decision, commit=False):
        d, err = self._open(decision_id, "prepare_decision")
        if err:
            return err
        result = validation.prepare(d.state, decision)
        out = {"ok": result["ok"], "errors": result["errors"], "diagnostics": result["diagnostics"],
               "costs": result["costs"], "seconds_left_in_this_turn": round(d.seconds_left(), 1)}
        if not result["ok"]:
            out["next"] = "fix the errors and prepare again; nothing was sent"
            return out
        draft_id = "draft-" + validation.fingerprint(result["batch"])
        d.drafts[draft_id] = result["batch"]
        out["draft_id"] = draft_id
        if commit:
            return {**out, **self._commit(d, draft_id)}
        out["next"] = "call commit_decision with this draft_id to send it, or prepare a changed decision"
        return out

    def commit_decision(self, decision_id, draft_id):
        d, err = self._open(decision_id, "commit_decision")
        if err:
            return err
        if draft_id not in d.drafts:
            return {"error": "UNKNOWN_DRAFT", "detail": "prepare the decision first; a changed decision needs a new draft"}
        return self._commit(d, draft_id)

    def _commit(self, d, draft_id):
        with d.state.lock:
            # the state may have moved since the draft was prepared: validate what is about to leave
            batch = d.drafts[draft_id]
            stale = [m["supplier_id"] for m in batch["emails"] if m["supplier_id"] not in d.state.ready()]
            if stale:
                return {"error": "STALE_STATE", "detail": f"{stale} can no longer be answered; read the state and prepare again"}
            d.batch, d.status = batch, "committed"
        d.done.set()
        return {"committed": True, "draft_id": draft_id,
                "next": "your decision is engaged and is being sent; end your turn now with one short line"}


def build_server(desk):
    """The MCP server over `desk`. Tool names and descriptions are what the model reads."""
    from mcp.server.mcpserver import MCPServer
    from mcp.types import ToolAnnotations

    mcp = MCPServer("tacto", instructions="A buyer's desk: read the case, compute costs, prepare and engage decisions.")
    ro = ToolAnnotations(readOnlyHint=True)

    @mcp.tool(annotations=ro)
    def get_case_state(decision_id: str) -> dict:
        """The current state of the case: mandate, cost of the alternative, and per supplier its
        standing sheet with what it costs us, its last e-mail, how far each side has moved, the
        seconds and messages left. Already included in each turn's message; call it again only
        to refresh."""
        return desk.get_case_state(decision_id)

    @mcp.tool(annotations=ro)
    def read_thread(decision_id: str, supplier_id: str) -> dict:
        """Every e-mail of one supplier thread in full, both directions, with the text of its
        attachments (quote PDF with its standard terms, cost breakdown, ...)."""
        return desk.read_thread(decision_id, supplier_id)

    @mcp.tool(annotations=ro)
    def evaluate_offers(decision_id: str, supplier_id: str, term_sheets: list[dict]) -> dict:
        """What each term sheet would cost us in EUR, by part, with this supplier's standard terms
        filling what a sheet leaves out. A term sheet is an object with the case's negotiable
        fields, e.g. {"unit_price": 50.25, "payment_days": 60}. Use it for sheets you consider
        sending and to compare the supplier's own sheets. Costs are computed, never guess them."""
        return desk.evaluate_offers(decision_id, supplier_id, term_sheets)

    @mcp.tool(annotations=ro)
    def search_structures(decision_id: str, supplier_id: str, target_cost_eur: float,
                          restrict: dict | None = None, limit: int = 12) -> dict:
        """You choose the total cost you aim at for us (EUR, same unit as cost_eur); this returns,
        for every allowed combination of the non-price terms, the exact unit price that makes it
        cost us that - sorted by price, highest first: at equal cost for us, the supplier prefers
        the higher price. `restrict` narrows the combinations, e.g. {"payment_days": [30, 45]}."""
        return desk.search_structures(decision_id, supplier_id, target_cost_eur, restrict, limit)

    @mcp.tool(annotations=ro)
    def lookup_facts(decision_id: str, ids: list[str]) -> dict:
        """The recorded values of data IDs (idx:, po:, quote:, sc:, cost:, fc:, news:, doc:, ctr:,
        offer:). The arena checks any ID you cite against these values."""
        return desk.lookup_facts(decision_id, ids)

    @mcp.tool(annotations=ro)
    def query_data(decision_id: str, sql: str, limit: int = 20) -> dict:
        """A read-only SQL query on the company's procurement data (orders, quotes, indices,
        scorecards, contracts, news). Start with: SELECT name FROM sqlite_master WHERE type='table'."""
        return desk.query_data(decision_id, sql, limit)

    @mcp.tool()
    def update_hypotheses(decision_id: str, notes: list[dict]) -> dict:
        """Your private notes on this case, kept across turns: what you believe about a supplier,
        what you asked, what remains unknown. Each note: {"id" (to revise one), "text", "status":
        supposed | supported | contradicted | withdrawn, "sources": [...]}. Revise a note when the
        supplier contradicts it."""
        return desk.update_hypotheses(decision_id, notes)

    @mcp.tool()
    def prepare_decision(decision_id: str, decision: dict, commit: bool = False) -> dict:
        """Check a decision before it is sent. `decision` is either
        {"emails": [{"supplier_id", "subject", "body", "term_sheets": [{...}, up to 3], "refs": [data IDs]}], "note": "why"}
        - at most one e-mail per supplier, several suppliers in one decision are sent in parallel -
        or {"close": {"type": "accept", "supplier_id", "term_sheet_id"}} or {"close": {"type": "walk_away"}}.
        Returns errors (must be fixed), diagnostics (facts to weigh; you may keep your choice) and
        the exact cost of every sheet. With commit=true a decision without errors is engaged at
        once; otherwise call commit_decision with the returned draft_id."""
        return desk.prepare_decision(decision_id, decision, commit)

    @mcp.tool()
    def commit_decision(decision_id: str, draft_id: str) -> dict:
        """Engage a prepared decision: it is sent exactly as prepared. One decision per turn."""
        return desk.commit_decision(decision_id, draft_id)

    return mcp


def free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


class ToolServer:
    """The MCP server on a local port, in a background thread of this process."""

    def __init__(self, desk, port=None):
        import uvicorn

        self.port = port or free_port()
        self.url = f"http://127.0.0.1:{self.port}/mcp"
        app = build_server(desk).streamable_http_app(json_response=True, stateless_http=True)
        self.server = uvicorn.Server(uvicorn.Config(app, host="127.0.0.1", port=self.port, log_level="warning"))
        self.thread = threading.Thread(target=self.server.run, name="tacto-mcp", daemon=True)

    def start(self, timeout=15.0):
        self.thread.start()
        end = time.monotonic() + timeout
        while time.monotonic() < end:
            if self.server.started:
                return self
            time.sleep(0.05)
        raise TimeoutError("the tool server did not start")

    def stop(self):
        self.server.should_exit = True
        self.thread.join(timeout=5)

"""Play one case with the DSH pilot: the model decides for the whole case, this loop executes.

One loop per case. When supplier e-mails await an answer it gives the model one turn, sized to
the earliest of their 60-second clocks; the committed decision's e-mails leave in parallel, one
request per supplier, and replies arriving meanwhile are added to the state for the next turn.
If the model has not committed in time, a fallback keeps the threads alive (it is marked as
such in the journal: a score obtained by fallbacks says nothing about the model).
"""

import json
import logging
import os
import threading
import time
from pathlib import Path

from arena_kit.client import ArenaError
from arena_kit.play import CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S, fetch_documents

from . import economics
from .state import CaseState

log = logging.getLogger("pegasus.dsh")

SEND_MARGIN_S = float(os.environ.get("PEGASUS_DSH_SEND_MARGIN_S", "12"))  # kept for validation, fallback and the network
MIN_TURN_S = 8.0  # with less than this the model is not asked at all
HOLDING_LINE = "We maintain the proposal below and look forward to your answer."
OPENING_QUESTION = ("Thank you for your quote. Before we answer in detail, could you send us the cost breakdown "
                    "behind your price?")


class Journal:
    """One JSON line per event of the game, next to the run's other files. Writing never raises."""

    def __init__(self, path=None):
        self.path, self.lock = (Path(path) if path else None), threading.Lock()
        if self.path:
            self.path.parent.mkdir(parents=True, exist_ok=True)

    def write(self, kind, **entry):
        if not self.path:
            return
        try:
            with self.lock, self.path.open("a", encoding="utf-8") as f:
                f.write(json.dumps({"t": round(time.time(), 2), "kind": kind, **entry}, default=str) + "\n")
        except OSError as e:
            log.warning("journal not written (%s)", e)


def closing_batch(state):
    """With no time or no message left: accept the cheapest signable sheet if it beats the
    alternative (or there is none), else walk away."""
    best, alt = state.best_standing(), economics.alternative(state.case)
    if best and (alt is None or best[0] < alt):
        return {"emails": [], "close": {"supplier_id": best[1], "message": {"action": {"type": "accept", "term_sheet_id": best[2]}}},
                "note": "fallback closing"}
    live = state.live()
    if not live:
        return None
    return {"emails": [], "close": {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}, "note": "fallback closing"}


def fallback_batch(state, ready, coded=None):
    """Keep the threads alive without the model: repeat our last sheets (what a timeout would do,
    without the lost patience); on a first move the coded agent's opening if one is given, else a
    question. A thread with no message left can only be closed."""
    emails = []
    for sid in ready:
        if state.moves_left(sid) <= 0:
            continue
        last = next((m for m in reversed(state.threads[sid]) if m.get("from") == "buyer" and m.get("term_sheets")), None)
        if last:
            emails.append({"supplier_id": sid, "message": {"subject": last.get("subject") or "Our proposal",
                                                         "body": HOLDING_LINE, "term_sheets": last["term_sheets"]}})
            continue
        move = None
        if coded is not None:
            try:
                move = coded.decide(state.case, state.threads, sid)
            except Exception:
                log.exception("%s %s: coded fallback failed", state.case["case_id"], sid)
        if move and move.get("message") and not move["message"].get("action") and move.get("supplier_id") == sid:
            emails.append({"supplier_id": sid, "message": move["message"]})
        else:
            emails.append({"supplier_id": sid, "message": {"subject": "Your quote", "body": OPENING_QUESTION, "term_sheets": []}})
    if emails:
        return {"emails": emails, "close": None, "note": "fallback"}
    return closing_batch(state)


def play_case(table, case_id, pilot, package=None, deadline=None, journal=None, coded=None):
    """Play one case to its end and return the arena's result. `deadline`: a Live Final wave's cap
    (time.time(), or a function returning it). `coded`: a coded agent used for a first move the
    model missed."""
    journal = journal or Journal()
    case, threads = table.open(case_id)
    if getattr(table, "done", None):
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    state = CaseState(case, threads, package)
    box, wake = {}, threading.Condition()
    slowest, turn = [0.0], 0
    journal.write("opened", case=case_id, session=getattr(table, "session_id", None), suppliers=list(threads),
                  c_open=state.c_open())

    def send(sid, message, t0):
        try:
            reply = table.send(sid, message)
        except ArenaError as e:
            journal.write("arena_error", case=case_id, supplier=sid, status=e.status, detail=str(e.detail)[:400])
            if e.status == 409:
                reply = table.missed(sid, e)
            else:  # 422: nothing happened, no round used - the model sees why on its next turn
                state.refused(sid, message, e.detail)
                with wake:
                    wake.notify_all()
                return
        except Exception as e:
            log.exception("%s %s: send failed", case_id, sid)
            state.refused(sid, message, f"send failed: {type(e).__name__}")
            with wake:
                wake.notify_all()
            return
        if "result" in reply:
            box["result"] = reply["result"]
        else:
            state.replied(sid, fetch_documents(table, reply))
            slowest[0] = max(slowest[0], time.monotonic() - t0)
            journal.write("reply", case=case_id, supplier=sid, status=reply.get("status"),
                          sheets=reply.get("term_sheets"), claim_results=reply.get("claim_results"),
                          cost=state.cost(sid, state.standing(sid)[1]) if state.standing(sid)[0] else None)
        with wake:
            wake.notify_all()

    def close(batch):
        target = batch["close"]
        try:
            box["result"] = table.close(target["supplier_id"], target["message"])
            return True
        except ArenaError as e:
            journal.write("arena_error", case=case_id, supplier=target["supplier_id"], status=e.status,
                          detail=str(e.detail)[:400], closing=True)
            if table.client.session(table.session_id).get("status") == "ended":
                box["result"] = table.result()
                return True
            state.errors[target["supplier_id"]] = f"close refused: {e.detail}"[:600]
            return False

    idle_since = None
    while "result" not in box:
        if not state.live():
            break
        cap = deadline() if callable(deadline) else deadline
        ready = state.ready()
        if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest[0] + ROUND_MARGIN_S):
            journal.write("cap_near", case=case_id)
            batch = closing_batch(state)
            if batch is None or close(batch):
                break
            continue
        if not ready:
            if not state.inflight:
                # nothing awaits us and nothing is out: threads we may not write to any more
                idle_since = idle_since or time.monotonic()
                if time.monotonic() - idle_since > 2:
                    batch = closing_batch(state)
                    if batch is None or close(batch):
                        break
            with wake:
                wake.wait(timeout=0.5)
            continue
        idle_since = None
        turn += 1
        t0 = time.monotonic()
        budget = min(state.seconds_left(s) for s in ready) - SEND_MARGIN_S
        decision, source = None, "model"
        if budget >= MIN_TURN_S:
            decision = pilot.decide(case_id, state, budget)
        if decision is not None and decision.status == "committed":
            batch = decision.batch
        else:
            source = "fallback"
            batch = fallback_batch(state, state.ready(), coded if turn == 1 else None)
        journal.write("decision", case=case_id, turn=turn, source=source, ready=ready, budget_s=round(budget, 1),
                      waited_s=getattr(decision, "waited_s", None), tools=getattr(decision, "calls", None),
                      trace=getattr(decision, "trace", None), batch=batch)
        if batch is None:
            break
        if batch.get("close"):
            if close(batch):
                break
            continue
        if not batch["emails"]:
            # the model answered nobody: do not spin on the same state
            fb = fallback_batch(state, state.ready())
            journal.write("decision", case=case_id, turn=turn, source="fallback", note="empty decision", batch=fb)
            if fb is None:
                break
            if fb.get("close"):
                if close(fb):
                    break
                continue
            batch = fb
        for mail in batch["emails"]:
            sid = mail["supplier_id"]
            if sid not in state.ready():
                continue
            state.sent(sid, mail["message"])
            threading.Thread(target=send, args=(sid, mail["message"], t0), name=f"send-{sid}", daemon=True).start()
    result = box.get("result") or table.result()
    journal.write("result", case=case_id, **{k: result.get(k) for k in
                                           ("deal", "score", "c_open", "c_deal", "c_best", "c_alt", "end_reason", "terms")})
    return result

