"""Which suppliers we have played does this one resemble, and what did those do next.

`suppliers.json` (built by `lab/dsh_suppliers.py` from every finished game we hold) is one record
per supplier we have met: who signs, how its offers answered our asks, when its final offer came,
what followed a push after it, what it wrote. During a game the same measures are taken on the
live thread and compared with each record. The closest records, with their weights, and what they
imply for the next reply are evidence for the model - what suppliers like this one did, never an
instruction.

Everything is in units a game shows: our cost of a sheet as a share of the supplier's opening
quote. A thread is a list of steps, ours and its:

    {"who": "B", "cost": cheapest sheet we sent (EUR, None without a sheet), "sheets": n}
    {"who": "S", "cost": its standing sheet (EUR, None when it left), "status": ..., "text": ...}
"""

import json
import math
import re
from functools import lru_cache
from pathlib import Path

RECORDS = Path(__file__).with_name("suppliers.json")
MIN_GAP = 0.005  # below half a percent of its quote, the gap between its offer and our ask says nothing
SPLIT = re.compile(r"(?<=[.!?])\s+|\n+")
NUMBER = re.compile(r"\d+(?:[.,]\d+)*")
SIGNED = re.compile(r"^([A-Z][A-Za-z ]{2,40}),\s+(.{3,80})$")
PRICED = ("our terms:", "alternatively", "our current angebot", "for this item")


def q(values, p):
    v = sorted(values)
    return v[min(len(v) - 1, int(p * len(v)))] if v else None


def spread(values, digits=3):
    """[q25, median, q75] of a list, None when empty."""
    return [round(q(values, p), digits) for p in (0.25, 0.5, 0.75)] if values else None


def sentences(text):
    """The sentences of an e-mail with their figures blanked, so that the same sentence said with
    another price is the same sentence. Lines that only state an offer are left out."""
    out = []
    for raw in SPLIT.split(text or ""):
        s = NUMBER.sub("#", raw.strip())
        if len(s) >= 12 and not s.lower().startswith(PRICED):
            out.append(s)
    return out


def signature(text):
    """(role, company) from the last line of an e-mail that reads `Role, Company`."""
    for line in reversed([x.strip() for x in (text or "").splitlines() if x.strip()]):
        m = SIGNED.match(line)
        if m:
            return m.group(1).strip(), m.group(2).strip()
    return None, None


def replies(steps):
    """One row per supplier reply to one of our e-mails. `gap` is what stood between its previous
    offer and our ask, `step` what it gave, `share` the part of the gap it closed, `our_move` how
    far our ask came up since our previous one - all as shares of its opening quote."""
    opening = next((s["cost"] for s in steps if s["who"] == "S" and s.get("cost")), None)
    rows, prev, ask_prev, pending, k = [], None, None, None, 0
    for s in steps:
        if s["who"] == "B":
            pending = s
            continue
        if prev is None or pending is None:
            prev = s if s.get("cost") is not None or prev is None else prev
            continue
        k += 1
        ask, offer, before = pending.get("cost"), s.get("cost"), prev.get("cost")
        row = {"k": k, "status": s.get("status"), "prev_status": prev.get("status"), "sheets": pending.get("sheets", 0)}
        if opening and before is not None:
            if ask is not None:
                row["gap"] = (before - ask) / opening
                row["ask_below_quote"] = (opening - ask) / opening
                if ask_prev is not None:
                    row["our_move"] = (ask - ask_prev) / opening
            if offer is not None:
                row["step"] = (before - offer) / opening
                row["offer_below_quote"] = (opening - offer) / opening
                if row.get("gap", 0) > MIN_GAP:
                    row["share"] = row["step"] / row["gap"]
        rows.append(row)
        ask_prev = ask if ask is not None else ask_prev
        prev = s if offer is not None else {**prev, "status": s.get("status")}
        pending = None
    return rows


def how_we_answered(row):
    """What our e-mail did, as the supplier may read it."""
    if "gap" not in row:
        return "a note without a term sheet"
    if row["gap"] <= 1e-6:
        return "we came up to its offer"
    return "we asked below its offer and had moved" if row.get("our_move", 1) > 1e-6 else "we asked below its offer without moving"


@lru_cache(maxsize=1)
def records():
    try:
        return json.loads(RECORDS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []


def _near(value, band, tolerance):
    """Log-weight of an observed value against a record's [q25, median, q75]: 0 inside the band,
    falling with the distance outside it, in units of `tolerance`."""
    if value is None or not band:
        return 0.0
    lo, _, hi = band
    d = max(lo - value, value - hi, 0.0)
    return -min(d / tolerance, 4.0)


def compare(context, rows, said, rec):
    """(log-weight, why) of one record against the live thread. Context first - who signs, the kind
    of case, how the supplier writes - then every reply it has given: its status at that reply, the
    share of the gap it closed."""
    w, why = 0.0, []
    if context.get("supplier") and context["supplier"] == rec["supplier"]:
        return 12.0, ["the same supplier in our records"]
    for key, gain, label in (
        ("who_signs", 1.4, "signed by the same role"),
        ("case_type", 0.7, "the same kind of case"),
        ("category_goal", 0.4, "the same category goal"),
    ):
        if context.get(key) and context[key] == rec.get(key):
            w += gain
            why.append(label)
    if context.get("bidders") and (context["bidders"] > 1) == (rec.get("bidders", 1) > 1):
        w += 0.4
    ours, theirs = set(context.get("negotiable") or []), set(rec.get("negotiable") or [])
    if ours and theirs:
        w += 0.8 * len(ours & theirs) / len(ours | theirs)
    known = rec.get("writes") or {}
    if said and known:
        hit = sum(known[s] for s in said if s in known)
        if hit:
            w += min(2.0, 0.5 * hit)
            why.append("writes the same sentences")
    for row in rows:
        by = (rec.get("status_by_reply") or {}).get(str(min(row["k"], 8))) or {}
        n = sum(by.values())
        if n:
            w += math.log((by.get(row["status"], 0) + 0.5) / (n + 2.0)) - math.log(1 / 4)
        band = (rec.get("first_reply") if row["k"] == 1 else rec.get("later_replies") or {}) or {}
        if "share" in row and band.get("share_of_gap"):
            fit = _near(row["share"], band["share_of_gap"], 0.15)
            w += 0.6 + fit
            if fit == 0.0:
                why.append(f"reply {row['k']} closed the same share of the gap")
    return w, why


def recognise(context, steps, said=(), hide_case=None, top=3):
    """The records closest to this supplier, with weights that sum to 1 over every record compared.
    `hide_case` leaves out the records of one case - to play a known case as if it were new."""
    rows = replies(steps)
    scored = []
    for rec in records():
        if hide_case and rec["case"] == hide_case:
            continue
        w, why = compare(context, rows, set(said), rec)
        scored.append((w, why, rec))
    if not scored:
        return {"replies_so_far": len(rows), "resembles": [], "rows": rows}
    peak = max(w for w, _, _ in scored)
    total = sum(math.exp(w - peak) for w, _, _ in scored)
    ranked = sorted(scored, key=lambda x: -x[0])
    return {
        "replies_so_far": len(rows),
        "rows": rows,
        "resembles": [
            {"weight": round(math.exp(w - peak) / total, 3), "why": why, "record": rec} for w, why, rec in ranked[:top]
        ],
        "all": [(math.exp(w - peak) / total, rec) for w, _, rec in ranked],
    }


def _mix(pairs):
    """Weighted median of (weight, value) pairs."""
    pairs = sorted((v, w) for w, v in pairs if v is not None and w > 0)
    total, run = sum(w for _, w in pairs), 0.0
    for v, w in pairs:
        run += w
        if run >= total / 2:
            return v
    return None


def outlook(found):
    """What the closest records say about the replies still to come: when their final offer came,
    which status followed at the next reply, what followed our e-mails after a final offer."""
    k, pool = found["replies_so_far"], found.get("all") or []
    nxt, finals, total = {}, {}, 0.0
    for w, rec in pool:
        by = (rec.get("status_by_reply") or {}).get(str(min(k + 1, 8))) or {}
        n = sum(by.values())
        for status, c in by.items():
            nxt[status] = nxt.get(status, 0.0) + w * c / n
        total += w if n else 0.0
        came = {int(a): c for a, c in (rec.get("final_offer_came_at_reply") or {}).items() if int(a) > k}
        m = sum(came.values())
        for a, c in came.items():
            finals[a] = finals.get(a, 0.0) + w * c / m
    out = {}
    if total:
        out["status_of_its_next_reply"] = {s: round(v / total, 2) for s, v in sorted(nxt.items(), key=lambda x: -x[1])}
    if finals:
        norm = sum(finals.values())
        out["its_final_offer_came_at_reply"] = {str(a): round(v / norm, 2) for a, v in sorted(finals.items())}
    return out


def forecast(found, standing, ask, opening):
    """Its next standing sheet, in our cost, if our cheapest sheet costs `ask`: the share of the
    gap it closed so far in this thread when it has shown one, mixed with what the closest records
    closed at this reply. Records that give a fixed step whatever the gap answer with that step."""
    if standing is None or ask is None or not opening:
        return None
    gap = (standing - ask) / opening
    if gap <= MIN_GAP:
        return {"note": "this sheet does not ask below its standing offer: it can only agree or hold"}
    k = found["replies_so_far"] + 1
    seen = [r["share"] for r in found["rows"] if r["k"] >= 2 and "share" in r and r.get("our_move", 1) > 1e-6]
    lows, mids, highs = [], [], []
    for w, rec in found.get("all") or []:
        part = rec.get("first_reply") if k == 1 else rec.get("later_replies")
        if not part:
            continue
        if part.get("law") == "a fixed step" and part.get("step_pct_of_its_quote"):
            band = [x / 100 for x in part["step_pct_of_its_quote"]]
        elif part.get("share_of_gap"):
            band = [x * gap for x in part["share_of_gap"]]
        else:
            continue
        lows.append((w, band[0]))
        mids.append((w, band[1]))
        highs.append((w, band[2]))
    if not mids:
        return None
    low, mid, high = _mix(lows), _mix(mids), _mix(highs)
    basis = "what the closest records gave at this reply"
    if seen and k >= 2:
        own = sorted(seen)[len(seen) // 2] * gap
        mid = (len(seen) * own + mid) / (len(seen) + 1)
        low, high = min(low, own, mid), max(high, own, mid)
        basis = f"the share of the gap it closed in this thread ({len(seen)} replies), mixed with the closest records"
    return {
        "if_it_moves_its_sheet_would_cost_us_eur": {
            "low_step": round(standing - low * opening, 2),
            "expected": round(standing - mid * opening, 2),
            "high_step": round(standing - high * opening, 2),
        },
        "expected_step_pct_of_its_quote": round(100 * mid, 2),
        "from": basis,
    }


def brief(rec):
    """A record as the model reads it: no bookkeeping, only what the supplier did."""
    keep = (
        "who_signs",
        "company",
        "case_type",
        "category_goal",
        "bidders",
        "games",
        "first_reply",
        "later_replies",
        "final_offer_came_at_reply",
        "after_its_final_offer",
        "it_left",
        "it_agreed_to_our_ask",
        "deepest_offer_below_its_quote_pct",
        "arguments",
        "inside_notes",
        "best_games",
    )
    return {"supplier": f"{rec['case']}/{rec['supplier']}", **{k: rec[k] for k in keep if rec.get(k) not in (None, {}, [])}}


def view(context, steps, said=(), hide_case=None):
    """What the state shows the model about one supplier."""
    found = recognise(context, steps, said, hide_case)
    if not found["resembles"]:
        return None, found
    rows = found["rows"]
    live = {
        "replies": len(rows),
        "share_of_gap_it_closed": [round(r["share"], 2) for r in rows if "share" in r],
        "its_steps_pct_of_its_quote": [round(100 * r["step"], 2) for r in rows if "step" in r],
        "it_held_when": [how_we_answered(r) for r in rows if r.get("step") is not None and r["step"] <= 1e-6],
    }
    out = {
        "note": "suppliers we have played that this one resembles, with weights; what they did is "
        "evidence, a new supplier may do otherwise",
        "suppliers_it_resembles": [
            {"weight": m["weight"], "why": m["why"], **brief(m["record"])} if i == 0
            else {"weight": m["weight"], "why": m["why"], **{k: v for k, v in brief(m["record"]).items() if k != "best_games"}}
            for i, m in enumerate(found["resembles"])
        ],
        "in_this_thread": live,
        **outlook(found),
    }
    return out, found

"""uv run python lab/dsh_suppliers.py [--check]  ->  hollerau/dsh/suppliers.json

One record per supplier we have played, from every finished game in `analysis/pegasus_data/`:
who signs, how its offers answered our asks, when its final offer came, what followed a push after
it, what it wrote and what its back office noted. `hollerau.dsh.recognition` compares a live
thread with these records. Offline: reads the archive, opens no session.

--check replays every archived reply as if its case were new (its records left out) and prints how
well the closest records foretold the status and the step of that reply.
"""

import glob
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path
from statistics import median

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
OUT = ROOT / "hollerau" / "dsh" / "suppliers.json"
DATA = ROOT / "analysis" / "pegasus_data"
BOILER = ("My call:", "Read the buyer's e-mail", "quote attached", "order confirmation attached", "delivery schedule")
CHECKED = (
    (re.compile(r"We checked the (.+?) data you cited; it holds and we took it into account"), "took it into account"),
    (re.compile(r"We checked the (.+?) data you cited; it holds, but it does not change"), "true, but it changed nothing"),
    (re.compile(r"We have already taken that (.+?) data into account"), "already counted"),
    (re.compile(r"The (.+?) data you cite does not concern"), "not about this part or company"),
    (re.compile(r"The (.+?) figures you cite do not match"), "wrong figure: it cost trust"),
)
MIN_ROWS = 5


def _cases():
    cases = {}
    for name in ("practice", "sandbox"):
        data = json.loads((DATA / f"cases-{name}.json").read_text())
        data = data if isinstance(data, list) else data.get("cases", data)
        for c in data.values() if isinstance(data, dict) else data:
            cases[c["case_id"]] = c
    return cases


def _cost(case, terms, fill):
    from arena_kit.cost import total_cost

    try:
        c = total_cost(case, {**fill, **{k: v for k, v in (terms or {}).items() if v is not None}})
        return None if c == float("inf") else c
    except Exception:
        return None


def threads():
    """Every supplier thread of the archive as recognition steps, with what only a finished game
    shows: the back office, the reasons, the result."""
    cases, out = _cases(), []
    for path in sorted(glob.glob(str(DATA / "sessions" / "*.json"))):
        d = json.loads(Path(path).read_text())
        s = d.get("session") or d
        r, case = s.get("result") or {}, cases.get(s.get("case_id"))
        if not case or not r.get("trace"):
            continue
        trace = r["trace"]
        sups = sorted({e["actor"] for e in trace if e.get("actor") != "buyer"})
        notes = defaultdict(list)
        for m in d.get("backoffice") or []:
            text = str(m.get("text"))
            if not text.startswith(BOILER):
                notes[m.get("supplier_id")].append(re.sub(r"\(.*?\)", "", re.sub(r"\d+(?:[.,]\d+)*", "#", text)).strip())
        by = defaultdict(list)
        for e in trace:
            m = e.get("move") or {}
            if e.get("actor") == "buyer":
                sid = m.get("supplier_id") or (sups[0] if len(sups) == 1 else None)
                if sid:
                    by[sid].append(("B", e, m))
            else:
                by[e["actor"]].append(("S", e, m))
        for sid, events in by.items():
            first = next((m for w, _, m in events if w == "S"), None)
            if not first:
                continue
            fill = {k: v for k, v in (first.get("terms") or {}).items() if k != "unit_price"}
            steps, reasons = [], []
            for w, e, m in events:
                if w == "B":
                    sheets = m.get("term_sheets") if isinstance(m.get("term_sheets"), list) else []
                    costs = [c for t in sheets if (c := _cost(case, t.get("terms") or t, fill)) is not None]
                    steps.append({"who": "B", "cost": min(costs) if costs else None, "sheets": len(sheets)})
                else:
                    terms = m.get("terms") or {}
                    fill = {**fill, **{k: v for k, v in terms.items() if k != "unit_price" and v is not None}}
                    gone = m.get("status") in ("walked_away", "no_bid") or terms.get("unit_price") is None
                    steps.append(
                        {
                            "who": "S",
                            "cost": None if gone else _cost(case, terms, fill),
                            "status": m.get("status"),
                            "text": m.get("text") or "",
                        }
                    )
                    reasons += e.get("reasons") or []
            out.append(
                {
                    "session": s["session_id"],
                    "case": s["case_id"].split(":")[-1],
                    "supplier": sid.split(":")[-1],
                    "case_type": case.get("type"),
                    "category_goal": case["buyer"].get("category_goal"),
                    "bidders": len(sups),
                    "negotiable": case["negotiable"],
                    "score": r.get("score"),
                    "deal_with": (r.get("supplier_id") or "").split(":")[-1] if r.get("deal") else None,
                    "end_reason": s.get("end_reason"),
                    "room": (r["c_open"] - r["c_best"]) / r["c_open"] if r.get("c_open") and r.get("c_best") else None,
                    "steps": steps,
                    "reasons": reasons,
                    "notes": notes.get(sid, []),
                }
            )
    return out


def _law(rows):
    """How the supplier's step relates to the gap between its offer and our ask, over the replies
    where we asked below its offer and had moved."""
    from hollerau.dsh.recognition import q, spread

    asked = [r for r in rows if r.get("gap", 0) > 0.005 and "step" in r]
    out = {"replies": len(asked)}
    if len(asked) < MIN_ROWS:
        return {**out, "law": "too few replies to say"}
    moved = [r for r in asked if r["step"] > 1e-6]
    out["it_moved"] = round(len(moved) / len(asked), 2)
    if moved:
        shares, steps = [r["share"] for r in moved], [r["step"] for r in moved]
        out["share_of_gap"] = spread(shares, 2)
        out["step_pct_of_its_quote"] = spread([100 * x for x in steps], 2)
        tight = lambda v: (q(v, 0.75) - q(v, 0.25)) / q(v, 0.5) if q(v, 0.5) else 9.0  # noqa: E731
        if out["it_moved"] < 0.25:
            out["law"] = "it holds its price"
        elif q(shares, 0.5) >= 0.9:
            out["law"] = "it meets our ask"
        elif tight(steps) < 0.15 and tight(steps) < tight(shares):
            out["law"] = "a fixed step"
        else:
            out["law"] = "a share of the gap"
    else:
        out["law"] = "it holds its price"
    return out


def record(games):
    """One supplier's record from all its threads."""
    from hollerau.dsh.recognition import how_we_answered, replies, sentences, signature, spread

    t0 = games[0]
    rows = [(g, replies(g["steps"])) for g in games]
    flat = [r for _, rr in rows for r in rr]
    opening_text = next((s["text"] for s in t0["steps"] if s["who"] == "S"), "")
    role, company = signature(opening_text)
    rec = {
        "supplier": t0["supplier"],
        "case": t0["case"],
        "who_signs": role,
        "company": company,
        "case_type": t0["case_type"],
        "category_goal": t0["category_goal"],
        "bidders": t0["bidders"],
        "negotiable": t0["negotiable"],
        "games": len(games),
        "replies": len(flat),
    }
    rooms = [g["room"] for g in games if g["room"] is not None]
    if rooms:
        rec["best_deal_possible_below_cheapest_quote_pct"] = round(100 * median(rooms), 1)
    first = [r for r in flat if r["k"] == 1]
    rec["first_reply"] = _law(first)
    asks = [100 * r["ask_below_quote"] for r in first if "ask_below_quote" in r]
    if asks:
        rec["first_reply"]["our_asks_were_pct_below_its_quote"] = spread(asks, 1)
        if rec["first_reply"].get("law") and max(asks) - min(asks) < 3:
            rec["first_reply"]["law"] = "our first asks were all alike: its rule is not told apart"
    later = [r for r in flat if r["k"] >= 2 and r["prev_status"] == "open"]
    rec["later_replies"] = _law([r for r in later if r.get("our_move", 1) > 1e-6])
    still = [r for r in later if "step" in r and r.get("gap", 0) > 0.005 and r.get("our_move", 1) <= 1e-6]
    if still:
        rec["later_replies"]["when_we_did_not_move"] = {
            "replies": len(still),
            "it_moved": round(sum(1 for r in still if r["step"] > 1e-6) / len(still), 2),
        }
    by = defaultdict(Counter)
    for r in flat:
        by[str(min(r["k"], 8))][r["status"]] += 1
    rec["status_by_reply"] = {k: dict(v) for k, v in sorted(by.items())}
    came = Counter()
    for _, rr in rows:
        k = next((r["k"] for r in rr if r["status"] == "final_offer"), None)
        if k:
            came[str(k)] += 1
    rec["final_offer_came_at_reply"] = dict(sorted(came.items()))
    after = defaultdict(Counter)
    for r in flat:
        if r["prev_status"] == "final_offer":
            after[how_we_answered(r)][r["status"]] += 1
    rec["after_its_final_offer"] = {k: dict(v) for k, v in after.items()}
    left = [r for r in flat if r["status"] in ("walked_away", "no_bid")]
    if left:
        rec["it_left"] = {
            "games": len(left),
            "at_reply": dict(sorted(Counter(str(r["k"]) for r in left).items())),
            "after": dict(Counter(f"its status was {r['prev_status']}; {how_we_answered(r)}" for r in left)),
        }
    agreed = [100 * r["offer_below_quote"] for r in flat if r["status"] == "agreed" and "offer_below_quote" in r]
    if agreed:
        rec["it_agreed_to_our_ask"] = {
            "replies": len(agreed),
            "at_pct_below_its_quote": spread(agreed, 1),
            "note": "it took our number as it stood: that ask was within what it accepts",
        }
    deep = [100 * r["offer_below_quote"] for r in flat if "offer_below_quote" in r]
    if deep:
        rec["deepest_offer_below_its_quote_pct"] = round(max(deep), 1)
    args = defaultdict(Counter)
    for g in games:
        for reason in g["reasons"]:
            for pattern, verdict in CHECKED:
                m = pattern.search(reason)
                if m:
                    args[m.group(1)][verdict] += 1
    rec["arguments"] = {k: dict(v) for k, v in sorted(args.items())}
    notes = Counter(n for g in games for n in g["notes"])
    rec["inside_notes"] = {n: c for n, c in notes.most_common(8)}
    said = Counter()
    mails = 0
    for g in games:
        for s in g["steps"]:
            if s["who"] == "S" and s.get("text"):
                mails += 1
                said.update(set(sentences(s["text"])))
    rec["_said"] = {s: c / mails for s, c in said.items() if c / mails >= 0.15}
    mine = [g for g in games if g["score"] is not None and (g["bidders"] == 1 or g["deal_with"] == g["supplier"])]
    seen, best = set(), []
    for g, rr in sorted(((g, replies(g["steps"])) for g in mine), key=lambda x: -x[0]["score"]):
        asks_ = tuple(round(100 * r["ask_below_quote"], 1) if "ask_below_quote" in r else None for r in rr)
        if asks_ in seen or not rr:
            continue
        seen.add(asks_)
        best.append(
            {
                "score": round(g["score"], 3),
                "ended": g["end_reason"],
                "our_asks_pct_below_its_quote": list(asks_),
                "its_offers_pct_below_its_quote": [
                    round(100 * r["offer_below_quote"], 1) if "offer_below_quote" in r else None for r in rr
                ],
                "its_status": [r["status"] for r in rr],
                "sheets_per_mail": [r["sheets"] for r in rr],
            }
        )
        if len(best) == 3:
            break
    rec["best_games"] = best
    scores = [g["score"] for g in mine if g["score"] is not None]
    if scores:
        rec["our_scores"] = {"games": len(scores), "median": round(median(scores), 3), "best": round(max(scores), 3)}
    return rec


def build(games=None):
    games = games or threads()
    by = defaultdict(list)
    for g in games:
        by[(g["case"], g["supplier"])].append(g)
    recs = [record(v) for _, v in sorted(by.items())]
    writers = Counter(s for r in recs for s in r["_said"])
    for r in recs:
        said = r.pop("_said")
        # a sentence weighs by how few suppliers write it: the persona shows in what only it says
        r["writes"] = {s: round(1 / writers[s], 2) for s, _ in sorted(said.items(), key=lambda x: -x[1])[:40]}
    return recs


def check(games):
    """Each archived reply foretold from the records of the OTHER cases: the weight given to the
    status that came, and the error on the step, against two plain guesses."""
    from hollerau.dsh import recognition as rec

    all_recs = build(games)
    by_case = defaultdict(list)
    for g in games:
        by_case[g["case"]].append(g)
    lines = []
    for case, gs in sorted(by_case.items()):
        others = [r for r in all_recs if r["case"] != case]
        rec.records.cache_clear()
        rec.records = lambda others=others: others  # the records of the other cases only
        flat_shares = [x for r in others for x in ([(r["later_replies"].get("share_of_gap") or [None] * 3)[1]]) if x]
        plain = median(flat_shares) if flat_shares else 0.15
        hit, base, err, err_plain, n_status, n_step = 0.0, 0.0, [], [], 0, 0
        for g in gs[:60]:
            steps = g["steps"]
            opening = next((s["cost"] for s in steps if s["who"] == "S" and s.get("cost")), None)
            first_text = next((s["text"] for s in steps if s["who"] == "S"), "")
            context = {
                "who_signs": rec.signature(first_text)[0],
                "case_type": g["case_type"],
                "category_goal": g["category_goal"],
                "bidders": g["bidders"],
                "negotiable": g["negotiable"],
            }
            idx = [i for i, s in enumerate(steps) if s["who"] == "S"]
            for n, i in enumerate(idx[1:], start=1):
                if steps[i - 1]["who"] != "B":
                    continue
                prefix = steps[: i - 1]
                said = {x for s in prefix if s["who"] == "S" for x in rec.sentences(s.get("text"))}
                found = rec.recognise(context, prefix, said)
                look = rec.outlook(found).get("status_of_its_next_reply") or {}
                actual = steps[i]
                hit += look.get(actual["status"], 0.0)
                base += 0.25
                n_status += 1
                standing = next((s["cost"] for s in reversed(prefix) if s["who"] == "S" and s.get("cost")), None)
                ask = steps[i - 1].get("cost")
                if standing and ask and actual.get("cost") and opening and (standing - ask) / opening > 0.005:
                    f = rec.forecast(found, standing, ask, opening)
                    if f and "if_it_moves_its_sheet_would_cost_us_eur" in f:
                        predicted = f["if_it_moves_its_sheet_would_cost_us_eur"]["expected"]
                        err.append(abs(predicted - actual["cost"]) / opening)
                        err_plain.append(abs(standing - plain * (standing - ask) - actual["cost"]) / opening)
                        n_step += 1
        if n_status:
            lines.append(
                f"{case}: {n_status} replies; weight on the status that came {hit / n_status:.2f} "
                f"(even guess {base / n_status:.2f}); step error, share of its quote: "
                f"records {100 * median(err):.2f} % against one share for all {100 * median(err_plain):.2f} % ({n_step} steps)"
                if err
                else f"{case}: {n_status} replies; weight on the status that came {hit / n_status:.2f}"
            )
    return lines


if __name__ == "__main__":
    games = threads()
    if "--check" in sys.argv:
        print("\n".join(check(games)))
    else:
        recs = build(games)
        OUT.write_text(json.dumps(recs, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
        print(f"{len(recs)} suppliers from {len(games)} threads -> {OUT.relative_to(ROOT)}")
        for r in recs:
            print(
                f"  {r['case']}/{r['supplier']:8} {str(r['who_signs']):20} games {r['games']:3}  first: {r['first_reply'].get('law')}"
                f"  later: {r['later_replies'].get('law')} {r['later_replies'].get('share_of_gap')}"
                f"  final at {r['final_offer_came_at_reply']}"
            )

